using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Forms;

namespace RockPro.CAD {
[System.Runtime.InteropServices.ComVisible(false)]
internal sealed class MaterialPlanForm : Form {
 readonly Func<string,object,Dictionary<string,object>> backend;
 readonly int uiThread=System.Threading.Thread.CurrentThread.ManagedThreadId;
 readonly Button reload=new Button(),next=new Button(),read=new Button(),compare=new Button(),export=new Button();
 readonly TextBox planId=new TextBox {Width=250,MaxLength=100},oldPlanId=new TextBox {Width=250,MaxLength=100};
 readonly Label heading=new Label(),status=new Label(),planCaption=new Label(),oldCaption=new Label();
 readonly DataGridView catalog=Grid(),groups=Grid(),progress=Grid(),changes=Grid(),orders=Grid();
 readonly TextBox sources=new TextBox {Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,WordWrap=false,ScrollBars=ScrollBars.Both};
 readonly TabControl tabs=new TabControl();
 readonly TabPage catalogTab=new TabPage(),groupTab=new TabPage(),progressTab=new TabPage(),changeTab=new TabPage(),orderTab=new TabPage(),sourceTab=new TabPage();
 Dictionary<string,object> currentPlan,comparison;
 DateTime? planReadAt,comparisonReadAt;
 string cursor,lastError="";bool busy,loading;
 static string T(string pl,string en){return LayoutLanguage.T(pl,en);}
 internal MaterialPlanForm():this(Rpc.Call,true){}
 internal MaterialPlanForm(Func<string,object,Dictionary<string,object>> call,bool autoLoad){
  backend=call;Size=new Size(1320,880);MinimumSize=new Size(1120,720);Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.Dpi;BackColor=Color.FromArgb(242,246,249);Padding=new Padding(18);StartPosition=FormStartPosition.CenterParent;
  var root=new TableLayoutPanel {Dock=DockStyle.Fill,ColumnCount=1,RowCount=5};root.RowStyles.Add(new RowStyle(SizeType.Absolute,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,95));Controls.Add(root);
  heading.Dock=DockStyle.Fill;heading.Padding=new Padding(10);heading.BackColor=Color.FromArgb(255,235,214);root.Controls.Add(heading,0,0);
  var tools=new FlowLayoutPanel {Dock=DockStyle.Fill,Padding=new Padding(0,8,0,0)};foreach(var button in new[]{reload,next,read,compare,export})Style(button);
  planCaption.AutoSize=true;planCaption.Margin=new Padding(6,9,5,0);planId.Margin=new Padding(0,4,8,0);tools.Controls.Add(reload);tools.Controls.Add(next);tools.Controls.Add(planCaption);tools.Controls.Add(planId);tools.Controls.Add(read);tools.Controls.Add(export);root.Controls.Add(tools,0,1);
  var comparisonTools=new FlowLayoutPanel {Dock=DockStyle.Fill};oldCaption.AutoSize=true;oldCaption.Margin=new Padding(0,9,5,0);oldPlanId.Margin=new Padding(0,4,8,0);comparisonTools.Controls.Add(oldCaption);comparisonTools.Controls.Add(oldPlanId);comparisonTools.Controls.Add(compare);root.Controls.Add(comparisonTools,0,2);
  catalogTab.Controls.Add(catalog);groupTab.Controls.Add(groups);progressTab.Controls.Add(progress);changeTab.Controls.Add(changes);orderTab.Controls.Add(orders);sourceTab.Controls.Add(sources);tabs.TabPages.AddRange(new[]{catalogTab,groupTab,progressTab,changeTab,orderTab,sourceTab});tabs.Dock=DockStyle.Fill;root.Controls.Add(tabs,0,3);status.Dock=DockStyle.Fill;status.Padding=new Padding(0,8,0,0);root.Controls.Add(status,0,4);
  reload.Click+=async delegate{await Run(async delegate{await LoadList(false);});};next.Click+=async delegate{await Run(async delegate{await LoadList(true);});};read.Click+=async delegate{await Run(ReadPlan);};compare.Click+=async delegate{await Run(Compare);};
  export.Click+=delegate{using(var dialog=new SaveFileDialog {Filter="JSON (*.json)|*.json",FileName=comparison==null?"odczyt-planu.json":"roznice-planow.json"})if(dialog.ShowDialog(this)==DialogResult.OK)try{ExportReport(dialog.FileName);}catch(Exception ex){lastError=ex.Message;Describe();}};
  catalog.SelectionChanged+=delegate{if(!loading&&catalog.SelectedRows.Count==1)planId.Text=Convert.ToString(catalog.SelectedRows[0].Cells[0].Value);};
  planId.TextChanged+=delegate{if(!loading){currentPlan=comparison=null;planReadAt=comparisonReadAt=null;lastError="";Render();Describe();UpdateButtons();}};
  oldPlanId.TextChanged+=delegate{if(!loading){comparison=null;comparisonReadAt=null;lastError="";Render();Describe();UpdateButtons();}};
  Shown+=async delegate{if(autoLoad)await Run(async delegate{await LoadList(false);});};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy)e.Cancel=true;};UiText.LanguageChanged+=RefreshLanguage;FormClosed+=delegate{UiText.LanguageChanged-=RefreshLanguage;};RefreshLanguage(null,EventArgs.Empty);UpdateButtons();
 }
 static void Style(Button button){button.Size=new Size(170,40);button.Margin=new Padding(0,0,8,4);button.BackColor=Color.White;}
 static DataGridView Grid(){var grid=new DataGridView {Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,MultiSelect=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize,BackgroundColor=Color.White};grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.DefaultCellStyle.Padding=new Padding(4,7,4,7);grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(255,229,208);grid.DefaultCellStyle.SelectionForeColor=Color.FromArgb(35,47,60);return grid;}
 static void Columns(DataGridView grid,string[] captions){if(grid.Columns.Count==0)for(int i=0;i<captions.Length;i++){int n=grid.Columns.Add("c"+i,captions[i]);grid.Columns[n].MinimumWidth=70;}for(int i=0;i<captions.Length;i++)grid.Columns[i].HeaderText=captions[i];}
 static string Value(Dictionary<string,object> row,string key){return !row.ContainsKey(key)||row[key]==null?"—":Convert.ToString(row[key]);}
 static string State(string key){switch(key){case "ready":return T("Gotowy według zapisu","Recorded ready");case "started":return T("Rozpoczęty wg operatora","Started per operator");case "outdated":return T("Nieaktualny","Outdated");case "changed_in_progress":return T("Wejście zmienione w trakcie","Inputs changed in progress");default:return key;}}
 async Task<Dictionary<string,object>> Call(string name,object args){return await Task.Run(()=>backend(name,args));}
 async Task Run(Func<Task> work){if(System.Threading.Thread.CurrentThread.ManagedThreadId!=uiThread)throw new InvalidOperationException("Material plan UI must start on its owner thread");System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());if(busy)return;busy=true;lastError="";UpdateButtons();status.Text=T("Odczyt planów i dowodów…","Reading plans and evidence…");try{await work();}catch(Exception ex){lastError=ex.Message;}finally{busy=false;Render();Describe();UpdateButtons();}}
 void UpdateButtons(){reload.Enabled=!busy;next.Enabled=!busy&&cursor!=null;read.Enabled=!busy&&planId.Text.Trim().Length>0;compare.Enabled=!busy&&currentPlan!=null&&oldPlanId.Text.Trim().Length>0;export.Enabled=!busy&&(comparison!=null||currentPlan!=null);planId.Enabled=oldPlanId.Enabled=tabs.Enabled=!busy;export.Text=comparison==null?T("Eksportuj odczyt…","Export plan read…"):T("Eksportuj różnice…","Export comparison…");}
 async Task LoadList(bool nextPage){var args=new Dictionary<string,object>{{"limit",100}};if(nextPage&&cursor!=null)args["after_plan_id"]=cursor;var reply=await Call("list_material_plans",args);loading=true;try{catalog.Rows.Clear();foreach(var item in Rpc.Rows(reply["plans"])){var row=Rpc.Obj(item);if(!Object.Equals(row["freshness_checked"],false))throw new Exception(T("Lista nie może udawać odczytu plików.","A listing must not impersonate file verification."));int index=catalog.Rows.Add(Value(row,"id"),row["revision"],State(Value(row,"recorded_status")),T("Niesprawdzona — użyj Odczytaj","Not checked — use Read"),Value(row,"created_at"),String.Join(", ",Array.ConvertAll(Rpc.Rows(row["project_ids"]),x=>Convert.ToString(x))),Value(row,"supersedes_plan_id"),Value(row,"scope")=="synthetic_test"?T("TEST syntetyczny","SYNTHETIC TEST"):T("Dane operatora","Operator input"));catalog.Rows[index].Tag=row;}catalog.ClearSelection();catalog.CurrentCell=null;cursor=reply["next_cursor"]==null?null:Rpc.Str(reply,"next_cursor");}finally{loading=false;}}
 async Task ReadPlan(){currentPlan=comparison=null;planReadAt=comparisonReadAt=null;Render();var reply=await Call("get_material_plan",new {plan_id=planId.Text.Trim()});if(!Object.Equals(reply["production_approved"],false))throw new Exception(T("Odczyt nie nadaje zgody produkcyjnej.","Reading does not approve production."));currentPlan=reply;planReadAt=DateTime.UtcNow;loading=true;try{var payload=Rpc.Obj(reply["payload"]);if(oldPlanId.Text.Trim().Length==0&&payload["supersedes_plan_id"]!=null)oldPlanId.Text=Rpc.Str(payload,"supersedes_plan_id");}finally{loading=false;}tabs.SelectedTab=groupTab;}
 async Task Compare(){comparison=null;comparisonReadAt=null;Render();var reply=await Call("compare_material_plans",new {old_plan_id=oldPlanId.Text.Trim(),new_plan_id=Rpc.Str(currentPlan,"id")});if(!Object.Equals(reply["inventory_reversed"],false)||!Object.Equals(reply["orders_cancelled"],false)||!Object.Equals(reply["production_approved"],false))throw new Exception(T("Odpowiedź wykracza poza raport porównania.","Response exceeds comparison-only scope."));comparison=reply;comparisonReadAt=DateTime.UtcNow;tabs.SelectedTab=changeTab;}
 void Render(){groups.Rows.Clear();progress.Rows.Clear();changes.Rows.Clear();orders.Rows.Clear();sources.Text="";if(currentPlan==null)return;var payload=Rpc.Obj(currentPlan["payload"]);var demand=Rpc.Obj(payload["demand"]);int index=0;
  foreach(var item in Rpc.Rows(demand["groups"])){var row=Rpc.Obj(item);groups.Rows.Add(++index,Value(row,"material_id"),Value(row,"finish"),Value(row,"technology_id"),Value(row,"cut_length_mm"),Value(row,"cut_width_mm"),Value(row,"thickness_mm"),row["quantity"],Value(row,"required_date"),Value(row,"grain_axis"));}
  foreach(var item in Rpc.Rows(currentPlan["progress"])){var row=Rpc.Obj(item);var e=Rpc.Obj(row["event"]);bool produced=Value(e,"type")=="produced";progress.Rows.Add(Value(row,"id"),Value(row,"created_at"),produced?T("Wykonanie wg operatora","Produced per operator"):T("Zobowiązanie wg operatora","Commitment per operator"),produced?(object)(Convert.ToInt32(e["group_index"])+1):"—",e["quantity"],Value(e,"reference"),Value(e,"item_id"),Value(e,"total_gross"),Value(e,"currency"),Value(e,"arrival_date"));}
  var text=new StringBuilder();text.AppendLine(T("ODCZYT PLANU (UTC): ","PLAN READ (UTC): ")+planReadAt.Value.ToString("o"));text.AppendLine(Value(currentPlan,"id")+" / v"+Value(currentPlan,"revision")+" / "+State(Value(currentPlan,"effective_status")));text.AppendLine("Payload SHA256: "+Value(currentPlan,"payload_sha256"));text.AppendLine("Verification SHA256: "+Value(payload,"verification_sha256"));text.AppendLine(T("Poprzedni plan: ","Superseded plan: ")+Value(payload,"supersedes_plan_id"));
  var json=new JavaScriptSerializer {MaxJsonLength=16000000};text.AppendLine("\n"+T("POWIĄZANIA BOM:\n","BOM BINDINGS:\n")+json.Serialize(demand["bindings"]));text.AppendLine("\n"+T("BIEŻĄCE WEJŚCIA / DIAGNOSTYKA:\n","CURRENT INPUTS / DIAGNOSTICS:\n")+json.Serialize(currentPlan["current_input_state"]));if(currentPlan.ContainsKey("input_diagnostics"))text.AppendLine(json.Serialize(currentPlan["input_diagnostics"]));
  if(comparison!=null){foreach(var item in Rpc.Rows(comparison["changes"])){var row=Rpc.Obj(item);var g=Rpc.Obj(row["new_group"]);changes.Rows.Add(Value(g,"material_id"),Value(g,"cut_length_mm"),Value(g,"cut_width_mm"),Value(g,"thickness_mm"),row["required_quantity"],row["reuse_candidate_quantity"],row["shortage_without_reuse"],row["shortage_if_reuse_accepted"],Value(g,"required_date"),T("Niezaakceptowane; jakość i termin do oceny","Not approved; quality and timing need review"));}
   foreach(var item in Rpc.Rows(comparison["committed_orders_preserved"])){var row=Rpc.Obj(item);orders.Rows.Add(Value(row,"reference"),Value(row,"item_id"),row["quantity"],Value(row,"total_gross"),Value(row,"currency"),Value(row,"arrival_date"));}
   text.AppendLine("\n"+T("ODCZYT RÓŻNIC (UTC): ","COMPARISON READ (UTC): ")+comparisonReadAt.Value.ToString("o"));text.AppendLine(Value(comparison,"old_plan_id")+" / v"+Value(comparison,"old_revision")+" → "+Value(comparison,"new_plan_id")+" / v"+Value(comparison,"new_revision"));
   text.AppendLine(State(Value(comparison,"old_status"))+" → "+State(Value(comparison,"new_status")));
   foreach(string field in new[]{"old_payload_sha256","new_payload_sha256","old_progress_sha256","new_progress_sha256"})text.AppendLine(field+": "+Value(comparison,field));
   text.AppendLine(T("Zachowany wydatek wg walut: ","Preserved expense by currency: ")+json.Serialize(comparison["committed_expense_by_currency"]));text.AppendLine(T("Koszt zmiany: ","Incremental cost: ")+Value(comparison,"incremental_cost")+T(" (wymaga aktualnej wyceny i akceptacji ponownego użycia)"," (requires current pricing and reuse acceptance)"));
  }sources.Text=text.ToString();foreach(var grid in new[]{groups,progress,changes,orders})grid.ClearSelection();
 }
 void Describe(){status.ForeColor=lastError.Length>0||currentPlan!=null&&Convert.ToBoolean(currentPlan["stale"])?Color.Firebrick:Color.FromArgb(55,75,95);
  if(lastError.Length>0){status.Text=lastError+T("\nOdczyt/porównanie niepotwierdzone. Nie zmieniono zapasu, zużycia ani zamówień.","\nRead/comparison unconfirmed. No inventory, consumption or orders were changed.");return;}
  if(currentPlan==null){status.Text=T("Lista pokazuje zapisane metadane. Wybierz plan lub wpisz jego ID i użyj Odczytaj, aby sprawdzić aktualność plików. Nic nie uruchamia produkcji.","The list shows stored metadata. Select a plan or enter its ID and use Read to check file freshness. Nothing starts production.");return;}
  string scope=Rpc.Str(Rpc.Obj(Rpc.Obj(currentPlan["payload"])["demand"]),"scope");status.Text=(scope=="synthetic_test"?T("TEST SYNTETYCZNY • ","SYNTHETIC TEST • "):T("DANE OPERATORA • ","OPERATOR INPUT • "))+Value(currentPlan,"id")+" / v"+Value(currentPlan,"revision")+" • "+State(Value(currentPlan,"effective_status"));
  if(comparison!=null)status.Text+="\n"+T("Wykonano: ","Produced: ")+Value(comparison,"produced_total")+T(" • Nieprzypisane wykonane: "," • Unallocated produced: ")+Value(comparison,"unallocated_produced_total")+T(" • Koszt zmiany: nieznany bez aktualnej wyceny."," • Incremental cost: unknown without current pricing.");
  status.Text+="\n"+T("Podgląd nie cofa zużycia ani zamówień. Ponowne użycie jest kandydatem do oceny jakości i terminu. Odczyt planu i porównanie mają osobne znaczniki czasu.","Review never reverses consumption or orders. Reuse requires quality and timing review. Plan and comparison reads have separate timestamps.");
 }
 void ExportReport(string path){object data=comparison!=null?(object)comparison:currentPlan;if(data==null)throw new Exception(T("Najpierw odczytaj plan.","Read a plan first."));var payload=new Dictionary<string,object>{{"schema_version",1},{"kind",comparison!=null?"material_plan_comparison_draft":"material_plan_read_draft"},{"read_at_utc",(comparison!=null?comparisonReadAt.Value:planReadAt.Value).ToString("o")},{"data",data},{"production_approved",false}};using(var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(stream,new UTF8Encoding(false)))writer.Write(new JavaScriptSerializer {MaxJsonLength=16000000}.Serialize(payload));}
 void RefreshLanguage(object sender,EventArgs e){if(IsDisposed)return;Text=T("RockPro | Wersje planów materiałowych","RockPro | Material plan revisions");heading.Text=T("ROCKPRO • PLANY MATERIAŁOWE — ODCZYT I RÓŻNICE\nMetadane → jawny odczyt planu → porównanie starej i nowej wersji. Aktualność źródła i snapshotu sprawdza backend.\nWykonane elementy i zobowiązania są oświadczeniami operatora. Kandydaci ponownego użycia wymagają oceny; koszt zmiany może pozostać nieznany.","ROCKPRO • MATERIAL PLANS — READ AND COMPARE\nMetadata → explicit plan read → old/new comparison. The backend checks source and snapshot freshness.\nProduced parts and commitments are operator claims. Reuse needs review; incremental cost may remain unknown.");
  reload.Text=T("Odśwież listę","Reload list");next.Text=T("Kolejna strona","Next page");read.Text=T("Odczytaj plan","Read plan");compare.Text=T("Porównaj ze starym","Compare with old");planCaption.Text=T("ID planu:","Plan ID:");oldCaption.Text=T("ID starego planu:","Old plan ID:");
  catalogTab.Text=T("Lista — metadane","List — metadata");groupTab.Text=T("Zapotrzebowanie planu","Plan demand");progressTab.Text=T("Zapisany postęp","Recorded progress");changeTab.Text=T("Różnice / kandydaci reuse","Changes / reuse candidates");orderTab.Text=T("Zachowane zobowiązania","Preserved commitments");sourceTab.Text=T("Źródła i znaczniki odczytu","Sources and read timestamps");
  foreach(DataGridViewRow item in catalog.Rows){var row=Rpc.Obj(item.Tag);item.Cells[2].Value=State(Value(row,"recorded_status"));item.Cells[3].Value=T("Niesprawdzona — użyj Odczytaj","Not checked — use Read");item.Cells[7].Value=Value(row,"scope")=="synthetic_test"?T("TEST syntetyczny","SYNTHETIC TEST"):T("Dane operatora","Operator input");}
  Columns(catalog,new[]{"ID",T("Wersja","Revision"),T("Stan zapisany","Recorded state"),T("Aktualność plików","File freshness"),T("Utworzono UTC","Created UTC"),T("Projekty","Projects"),T("Zastępuje","Supersedes"),T("Pochodzenie","Provenance")});
  Columns(groups,new[]{T("Grupa","Group"),T("Materiał","Material"),T("Wykończenie","Finish"),T("Technologia","Technology"),"L [mm]","W [mm]","T [mm]",T("Ilość","Quantity"),T("Termin","Required date"),T("Kierunek włókien","Grain axis")});
  Columns(progress,new[]{T("ID zdarzenia","Event ID"),T("Czas UTC","UTC time"),T("Rodzaj","Kind"),T("Grupa (od 1)","Group (from 1)"),T("Ilość","Quantity"),T("Referencja","Reference"),T("Materiał / SKU","Item / SKU"),T("Brutto","Gross"),T("Waluta","Currency"),T("Dostawa","Arrival")});
  Columns(changes,new[]{T("Materiał","Material"),"L [mm]","W [mm]","T [mm]",T("Nowa potrzeba","New demand"),T("Kandydat reuse","Reuse candidate"),T("Brak bez reuse","Shortage without reuse"),T("Warunkowy brak po reuse","Conditional shortage after reuse"),T("Nowy termin","New required date"),T("Ocena ponownego użycia","Reuse review")});
  Columns(orders,new[]{T("Referencja","Reference"),T("Materiał / SKU","Item / SKU"),T("Ilość","Quantity"),T("Brutto","Gross"),T("Waluta","Currency"),T("Dostawa","Arrival")});Render();Describe();UpdateButtons();
 }
}
